const body = $input.first().json.body || $input.first().json;
const client_code = (body.client_code || body.clientCode || '').trim();
if (!client_code) throw new Error('client_code is required');
return [{ json: { client_code } }];

const items = $input.all();
if (!items || items.length === 0 || !items[0].json) {
  throw new Error('No client found. Check client_code in the Client Database.');
}
const row = items[0].json;
function c(v) { return v === undefined || v === null ? '' : String(v).trim(); }

const brief = {
  client_code: c(row.client_code),
  brand_name: c(row.brand_name),
  client_name: c(row.client_name),
  client_email: c(row.client_email),
  website_url: c(row.website_url),
  product_feature: c(row.product_feature),
  differentiator: c(row.differentiator),
  competitors: c(row.competitors),
  competitor_strengths: c(row.competitor_strengths),
  target_user: c(row.target_user),
  biggest_problem: c(row.biggest_problem),
  main_hesitation: c(row.main_hesitation),
  social_proof: c(row.social_proof),
  selling_proposition: c(row.selling_proposition),
  brand_personality: c(row.brand_personality),
  credibility_point: c(row.credibility_point),
  transformation: c(row.transformation),
  best_concepts: c(row.best_concepts),
  compliance: c(row.compliance),
  reference_ads: c(row.reference_ads),
  available_assets: c(row.available_assets),
  do_not_say: c(row.do_not_say),
  additional_notes: c(row.additional_notes),
  num_scripts: parseInt(c(row.num_scripts)) || 3
};

const required = ['brand_name', 'product_feature', 'target_user'];
const missing = required.filter(f => !brief[f]);
if (missing.length > 0) throw new Error('Brief missing: ' + missing.join(', '));

return [{ json: { brief, revision_count: 0 } }];

const brief = $('Validate Brief').first().json.brief;
const projectRecord = $input.first().json;
const project_id = projectRecord.id;

const prompt = `DEEP RESEARCH MISSION for ${brief.brand_name}.

You have 5 research tools. USE ALL OF THEM to gather real intelligence.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Selling Proposition: ${brief.selling_proposition}
Website: ${brief.website_url}
Competitors: ${brief.competitors}
Competitor Strengths: ${brief.competitor_strengths}
Target User: ${brief.target_user}
Biggest Problem: ${brief.biggest_problem}
Main Hesitation: ${brief.main_hesitation}
Transformation: ${brief.transformation}
Brand Personality: ${brief.brand_personality}
Credibility: ${brief.credibility_point}
Social Proof: ${brief.social_proof}
Reference Ads: ${brief.reference_ads || 'Not specified'}

== YOUR RESEARCH TASKS (do ALL of these) ==

1. READ THE BRAND WEBSITE: Use read_website on ${brief.website_url || 'the brand website'} to understand their product, pricing, and claims.

2. MINE AMAZON/MARKETPLACE REVIEWS: Use amazon_review_search for "${brief.product_feature}" to find real customer language. Then use read_website on the top 2-3 review pages.

3. SEARCH REDDIT: Use reddit_search for "${brief.biggest_problem}" AND for "${brief.product_feature}". Extract real discussions, pain points, and the exact words people use.

4. RESEARCH COMPETITOR ADS: Use competitor_ad_search for each competitor: ${brief.competitors || 'the main competitors in this space'}. Find what ads they are running.

5. CHECK SOCIAL SENTIMENT: Use google_search for "${brief.brand_name} review" and "${brief.product_feature} TikTok". See what real people are saying.

6. MINE VIRAL CONCEPTS ACROSS ALL PLATFORMS (CRITICAL):
   a) TikTok: Use tiktok_viral_search for "${brief.product_feature}" and "${brief.biggest_problem}"
   b) Instagram: Use instagram_viral_search for "${brief.product_feature} Reel" and the product category
   c) Meta Ad Library: Use meta_ad_library_search for EACH competitor: ${brief.competitors || 'competitors in this space'} — find their ACTIVE paid ads
   d) Competitor ads: Use competitor_ad_search for general ad breakdowns
   Find 10-15 references total across platforms (mix organic + paid). For each, note URL, platform, format, hook, why it works, and how it adapts to ${brief.brand_name}.

== REQUIRED OUTPUT FORMAT ==

You MUST output your research in the following structured format so it can be parsed and stored:

=== VOC_QUOTES_START ===
For each VOC quote found, output on a single line:
VOC|<category: Pain/Desire/Proof/Objection/Language>|<source: Amazon/Reddit/Forum/Brand Website/Google/TikTok/Instagram>|<relevance: High/Medium/Low>|<the actual quote text>
=== VOC_QUOTES_END ===

=== INSIGHTS_START ===
For each insight, output on a single line:
INSIGHT|<type: Competitor Intel/Market Trend/Audience Insight/Script Ammunition>|<source>|<category: Competitor Gap/Trend/Pain/Desire/Proof/Objection/Language>|<relevance: High/Medium/Low>|<the insight text>
=== INSIGHTS_END ===

=== REFERENCE_VIDEOS_START ===
For each reference video/ad found, output on a single line:
REF|<url>|<platform: TikTok/Instagram Reels/Facebook Ad/Instagram Ad/YouTube Shorts>|<type: Organic Viral/Paid Ad/UGC Ad/Creator Content>|<format: Talking Head/GRWM/Before-After/Unboxing/POV/Storytime/Routine/Transformation/Comparison/Green Screen/Testimonial Ad/Product Demo>|<hook text>|<why it works>|<adaptation idea>|<engagement info>
=== REFERENCE_VIDEOS_END ===

After the structured sections, include your full narrative research report with all analysis sections (Brand Analysis, VOC Goldmine narrative, Competitor Landscape, Audience Psychology, Market Gap, Script Ammunition, Format Trend Map).

Do NOT skip the tool research. The entire value of this agent is real data, not AI assumptions.`;

return [{ json: { prompt, brief, project_id } }];

// ============================================================
// Parse research output into structured Airtable records
// Extracts VOC quotes, insights, and reference videos
// ============================================================

const researchOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const brief = $('Build Research Prompt').first().json.brief;
const project_id = $('Build Research Prompt').first().json.project_id;

// Parse VOC quotes
const vocRecords = [];
const vocMatch = researchOutput.match(/=== VOC_QUOTES_START ===[\s\S]*?=== VOC_QUOTES_END ===/i);
if (vocMatch) {
  const lines = vocMatch[0].split('\n').filter(l => l.startsWith('VOC|'));
  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length >= 5) {
      vocRecords.push({
        project_id: project_id,
        research_type: 'VOC Quote',
        category: (parts[1] || 'Pain').trim(),
        source: (parts[2] || 'Unknown').trim(),
        relevance: (parts[3] || 'Medium').trim(),
        content: (parts[4] || '').trim()
      });
    }
  }
}

// Parse insights
const insightRecords = [];
const insightMatch = researchOutput.match(/=== INSIGHTS_START ===[\s\S]*?=== INSIGHTS_END ===/i);
if (insightMatch) {
  const lines = insightMatch[0].split('\n').filter(l => l.startsWith('INSIGHT|'));
  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length >= 6) {
      insightRecords.push({
        project_id: project_id,
        research_type: (parts[1] || 'Market Trend').trim(),
        source: (parts[2] || 'Unknown').trim(),
        category: (parts[3] || 'Trend').trim(),
        relevance: (parts[4] || 'Medium').trim(),
        content: (parts[5] || '').trim()
      });
    }
  }
}

// Parse reference videos
const refRecords = [];
const refMatch = researchOutput.match(/=== REFERENCE_VIDEOS_START ===[\s\S]*?=== REFERENCE_VIDEOS_END ===/i);
if (refMatch) {
  const lines = refMatch[0].split('\n').filter(l => l.startsWith('REF|'));
  for (const line of lines) {
    const parts = line.split('|');
    if (parts.length >= 9) {
      refRecords.push({
        project_id: project_id,
        url: (parts[1] || '').trim(),
        platform: (parts[2] || 'TikTok').trim(),
        type: (parts[3] || 'Organic Viral').trim(),
        format: (parts[4] || 'Talking Head').trim(),
        hook: (parts[5] || '').trim(),
        why_it_works: (parts[6] || '').trim(),
        adaptation_idea: (parts[7] || '').trim(),
        engagement: (parts[8] || '').trim()
      });
    }
  }
}

// If structured parsing failed, create fallback records from the raw output
if (vocRecords.length === 0) {
  vocRecords.push({
    project_id: project_id,
    research_type: 'VOC Quote',
    category: 'Pain',
    source: 'Research Agent',
    relevance: 'High',
    content: 'Research output could not be parsed into structured VOC quotes. See full research report in narrative form.'
  });
}

if (refRecords.length === 0) {
  refRecords.push({
    project_id: project_id,
    url: '',
    platform: 'TikTok',
    type: 'Organic Viral',
    format: 'Talking Head',
    hook: 'N/A',
    why_it_works: 'Reference videos could not be parsed from structured output.',
    adaptation_idea: '',
    engagement: ''
  });
}

const allResearch = [...vocRecords, ...insightRecords];

return [{ json: {
  project_id,
  brief,
  research_records: allResearch,
  reference_records: refRecords,
  research_output: researchOutput,
  research_count: allResearch.length,
  reference_count: refRecords.length
} }];

// ============================================================
// Split research records into individual items for Airtable batch create
// ============================================================
const data = $input.first().json;
const items = data.research_records.map(record => ({ json: record }));
return items;

// ============================================================
// Split reference video records into individual items for Airtable
// ============================================================
const data = $('Parse Research Output').first().json;
const items = data.reference_records.map(record => ({ json: record }));
return items;

// ============================================================
// Wait for both Airtable stores to finish, then proceed
// Collect reference video Airtable IDs for concept linking
// ============================================================
const data = $('Parse Research Output').first().json;
return [{ json: {
  project_id: data.project_id,
  brief: data.brief,
  research_output: data.research_output,
  research_count: data.research_count,
  reference_count: data.reference_count
} }];

// ============================================================
// Build Strategy Agent prompt with brief + research output
// ============================================================

const data = $('Merge Store Results').first().json;
const brief = data.brief;
const researchOutput = data.research_output;
const project_id = data.project_id;

const numConcepts = Math.ceil(brief.num_scripts * 1.5);

const prompt = `You have deep research from our Research Analyst. Now develop the creative strategy.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Target: ${brief.target_user}
Problem: ${brief.biggest_problem}
Hesitation: ${brief.main_hesitation}
Transformation: ${brief.transformation}
Personality: ${brief.brand_personality}
Social Proof: ${brief.social_proof}
Credibility: ${brief.credibility_point}
Best Concepts: ${brief.best_concepts || 'Not specified'}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}
Scripts Ordered: ${brief.num_scripts}
Concepts to Present: ${numConcepts}

== RESEARCH REPORT ==
${researchOutput}

== YOUR TASK ==
Develop ${numConcepts} UNIQUE creative concepts.

CRITICAL: You MUST output your concepts in this STRUCTURED JSON format so they can be parsed and stored:

\`\`\`json
{
  "concepts": [
    {
      "concept_name": "The Skeptic Convert",
      "reference_video_url": "URL from research",
      "reference_platform": "TikTok",
      "framework": "PAS",
      "hook_type": "controversy",
      "hook_text": "Stop buying vitamin C serums. Here's why.",
      "format": "Talking Head",
      "funnel_stage": "TOF",
      "virality_score": 8,
      "concept_pitch": "One-line pitch for the client",
      "emotional_journey": "frustration > curiosity > relief > desire",
      "target_objection": "They all oxidize and turn orange",
      "platform": "TikTok",
      "ab_test_pair": "Name of paired concept or null"
    }
  ]
}
\`\`\`

For EACH concept provide ALL fields listed above.

DIVERSITY RULES:
- Each concept MUST use a DIFFERENT framework + hook type combination
- At least 4 different UGC video formats
- Mix funnel stages: at least 2 TOF, 1-2 MOF, 1-2 BOF
- Mix platforms
- At least one concept under 20 seconds
- Include at least 1 A/B test pair

Output ONLY valid JSON.`;

return [{ json: { prompt, brief, project_id } }];

// ============================================================
// Parse Strategy Agent output into concept records for Airtable
// ============================================================

const strategyOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const project_id = $('Build Strategy Prompt').first().json.project_id;
const brief = $('Build Strategy Prompt').first().json.brief;

let concepts = [];
try {
  const parsed = JSON.parse(strategyOutput);
  concepts = parsed.concepts || [parsed];
} catch(e) {
  const match = strategyOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      concepts = parsed.concepts || [parsed];
    } catch(e2) {
      // Fallback: create a single concept from text
      concepts = [{
        concept_name: 'Concept from Strategy',
        framework: 'PAS',
        hook_type: 'curiosity-gap',
        hook_text: 'N/A — see strategy output',
        format: 'Talking Head',
        funnel_stage: 'TOF',
        virality_score: 5,
        concept_pitch: 'Strategy output could not be parsed into structured concepts.',
        emotional_journey: 'N/A',
        target_objection: 'N/A',
        platform: 'TikTok',
        ab_test_pair: null,
        reference_video_url: '',
        reference_platform: 'TikTok'
      }];
    }
  }
}

const conceptRecords = concepts.map(c => ({
  project_id: project_id,
  concept_name: c.concept_name || 'Unnamed Concept',
  reference_video_url: c.reference_video_url || '',
  reference_platform: c.reference_platform || 'TikTok',
  framework: c.framework || 'PAS',
  hook_type: c.hook_type || 'curiosity-gap',
  hook_text: c.hook_text || '',
  format: c.format || 'Talking Head',
  funnel_stage: c.funnel_stage || 'TOF',
  virality_score: parseInt(c.virality_score) || 5,
  concept_pitch: c.concept_pitch || '',
  emotional_journey: c.emotional_journey || '',
  target_objection: c.target_objection || '',
  platform: c.platform || 'TikTok',
  ab_test_pair: c.ab_test_pair || '',
  pm_status: 'Pending',
  client_status: 'Pending',
  overall_status: 'PM Review'
}));

return [{ json: {
  project_id,
  brief,
  concept_records: conceptRecords,
  concept_count: conceptRecords.length,
  strategy_output: strategyOutput
} }];

// Split concept records into individual items for Airtable
const data = $input.first().json;
const items = data.concept_records.map(record => ({ json: record }));
return items;

// ============================================================
// Build Slack notification with concept summary + approval buttons
// ============================================================
const data = $('Parse Concepts Output').first().json;
const brief = data.brief;
const concepts = data.concept_records;
const project_id = data.project_id;

const conceptSummary = concepts.map((c, i) => 
  `${i + 1}. *${c.concept_name}* (${c.framework} / ${c.format}) — Virality: ${c.virality_score}/10\n   _"${c.hook_text}"_\n   Pitch: ${c.concept_pitch}`
).join('\n\n');

const slackBlocks = [
  {
    "type": "header",
    "text": { "type": "plain_text", "text": `Concepts Ready for Review: ${brief.brand_name}` }
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*${concepts.length} concepts generated for ${brief.client_code}*\nClient: ${brief.client_name}\nScripts ordered: ${brief.num_scripts} | Concepts presented: ${concepts.length}\n\n${conceptSummary}`
    }
  },
  {
    "type": "divider"
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": "Review concepts in Airtable, then approve or reject below."
    }
  },
  {
    "type": "actions",
    "elements": [
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "Approve All Concepts" },
        "style": "primary",
        "url": `http://n8n-jeet.duckdns.org:5678/webhook/ugc-concept-approval?project_id=${project_id}&action=pm_approve`
      },
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "Review in Airtable" },
        "url": `https://airtable.com/appvFxwZc9yU8o8pK/Concepts?filter_project_id=${project_id}`
      }
    ]
  }
];

return [{ json: {
  project_id,
  brief,
  concept_count: concepts.length,
  slack_blocks: JSON.stringify(slackBlocks),
  slack_text: `${concepts.length} UGC concepts ready for PM review: ${brief.brand_name} (${brief.client_code})`
} }];

const err = $input.first().json;
let brand = 'Unknown', code = 'N/A';
try { const b = $('Validate Brief').first().json.brief; brand = b.brand_name; code = b.client_code; } catch(e) {}
return [{ json: { brand_name: brand, client_code: code, error_message: err.error?.message || err.message || 'Unknown', error_node: err.error?.node?.name || 'Unknown', timestamp: new Date().toISOString() } }];
